// Build the bash search script as an array of lines.
// Using single-quoted JS strings avoids TypeScript misinterpreting bash ${VAR} as template expressions.

export function generateSearchScript(dbFilename: string): string {
  const lines = [
    '#!/usr/bin/env bash',
    '# Overview search — queries the code index database',
    '# Generated by: overview index',
    '#',
    '# Usage:',
    '#   .overview/search "query"                  search everything',
    '#   .overview/search "query" --only files     only files',
    '#   .overview/search "query" --only symbols   only functions/classes',
    '#   .overview/search "query" --only imports   only import relations',
    '#   .overview/search "query" --module Auth    filter by module',
    '#   .overview/search "query" --kind view      filter by kind',
    '#   .overview/search "query" --limit 20       more results (default: 10)',
    '',
    `DB="$(dirname "$0")/${dbFilename}"`,
    '',
    'if [ ! -f "$DB" ]; then',
    '  echo \'{"error":"Database not found. Run: overview index"}\' >&2',
    '  exit 1',
    'fi',
    '',
    'if ! command -v sqlite3 &>/dev/null; then',
    '  echo \'{"error":"sqlite3 not found. Install: brew install sqlite"}\' >&2',
    '  exit 1',
    'fi',
    '',
    'QUERY=""',
    'ONLY=""',
    'MODULE=""',
    'KIND=""',
    'LIMIT=10',
    '',
    'while [[ $# -gt 0 ]]; do',
    '  case "$1" in',
    '    --only)   ONLY="$2";   shift 2 ;;',
    '    --module) MODULE="$2"; shift 2 ;;',
    '    --kind)   KIND="$2";   shift 2 ;;',
    '    --limit)  LIMIT="$2";  shift 2 ;;',
    '    -h|--help)',
    '      grep "^#" "$0" | sed \'s/^# //;s/^#//\'',
    '      exit 0 ;;',
    '    *) QUERY="$1"; shift ;;',
    '  esac',
    'done',
    '',
    'if [ -z "$QUERY" ]; then',
    '  echo "Usage: .overview/search \\"query\\" [--only files|symbols|imports] [--module name] [--kind kind] [--limit n]" >&2',
    '  exit 1',
    'fi',
    '',
    '# Escape double-quotes in query for FTS5 phrase search',
    'SAFE_FTS="${QUERY//\"/\\\"}"',
    'SAFE_FTS="\\"${SAFE_FTS}\\""',
    '',
    '# Escape for LIKE (used for import path search)',
    'SAFE_LIKE="%${QUERY//%/\\%}%"',
    '',
    '# Optional WHERE clauses',
    'MOD_FILTER=""',
    'KIND_FILTER=""',
    '[ -n "$MODULE" ] && MOD_FILTER="AND f.module = \'${MODULE//\'/\'\'}\'"',
    '[ -n "$KIND"   ] && KIND_FILTER="AND f.kind   = \'${KIND//\'/\'\'}\'"',
    '',
    'search_files() {',
    '  sqlite3 "$DB" -json "',
    '    SELECT f.path, f.module, f.layer, f.kind, f.description, f.tags',
    '    FROM files f',
    '    WHERE f.rowid IN (SELECT rowid FROM files_fts WHERE files_fts MATCH $SAFE_FTS)',
    '    $MOD_FILTER $KIND_FILTER',
    '    LIMIT $LIMIT;"',
    '}',
    '',
    'search_symbols() {',
    '  sqlite3 "$DB" -json "',
    '    SELECT s.name, s.type, s.description, s.line, s.file_path as file, f.module, f.kind',
    '    FROM symbols s JOIN files f ON f.path = s.file_path',
    '    WHERE s.id IN (SELECT rowid FROM symbols_fts WHERE symbols_fts MATCH $SAFE_FTS)',
    '    $MOD_FILTER $KIND_FILTER',
    '    LIMIT $LIMIT;"',
    '}',
    '',
    'search_imports() {',
    '  sqlite3 "$DB" -json "',
    "    SELECT 'uses' as direction, to_path as path FROM imports",
    "    WHERE from_path LIKE '$SAFE_LIKE' ESCAPE '\\\\'",
    '    UNION ALL',
    "    SELECT 'used_by', from_path FROM imports",
    "    WHERE to_path LIKE '$SAFE_LIKE' ESCAPE '\\\\'",
    '    LIMIT $LIMIT;"',
    '}',
    '',
    'E() { [ -n "$1" ] && echo "$1" || echo "[]"; }',
    '',
    'case "$ONLY" in',
    '  files)',
    '    F=$(search_files)',
    '    printf \'{"query":"%s","files":%s}\\n\' "$QUERY" "$(E "$F")" ;;',
    '  symbols)',
    '    S=$(search_symbols)',
    '    printf \'{"query":"%s","symbols":%s}\\n\' "$QUERY" "$(E "$S")" ;;',
    '  imports)',
    '    I=$(search_imports)',
    '    printf \'{"query":"%s","imports":%s}\\n\' "$QUERY" "$(E "$I")" ;;',
    '  "")',
    '    F=$(search_files)',
    '    S=$(search_symbols)',
    '    I=$(search_imports)',
    '    printf \'{"query":"%s","files":%s,"symbols":%s,"imports":%s}\\n\' \\',
    '      "$QUERY" "$(E "$F")" "$(E "$S")" "$(E "$I")" ;;',
    '  *)',
    '    echo "Unknown --only: $ONLY (use: files, symbols, imports)" >&2',
    '    exit 1 ;;',
    'esac',
  ];
  return lines.join('\n') + '\n';
}
